// RosterPlayer is a Dynasty API schema.
type RosterPlayer struct {
	PlayerKey int                   `json:"player_key"`
	TeamKey   int                   `json:"team_key"`
	Name      string                `json:"name"`
	FirstName string                `json:"first_name"`
	LastName  string                `json:"last_name"`
	Jersey    int                   `json:"jersey"`
	Position  string                `json:"position"`
	Archetype string                `json:"archetype"`
	Overall   int                   `json:"overall"`
	ClassYear RosterPlayerClassYear `json:"class_year"`
	// `NE`, `NI`, `CU` (redshirting this season) or `PR` (redshirted before)
	Redshirt string `json:"redshirt"`
	// `CU` or `PR`
	Redshirted bool                 `json:"redshirted"`
	DevTrait   RosterPlayerDevTrait `json:"dev_trait"`
	// Inches
	Height int `json:"height"`
	// Pounds
	Weight   int    `json:"weight"`
	Hometown string `json:"hometown"`
	// In the game's NIL units
	NILCompensation int `json:"nil_compensation"`
	// Current ratings by name: `speed`, `throwPower`, `zoneCoverage`, ...
	Ratings   map[string]int `json:"ratings"`
	Abilities []Ability      `json:"abilities"`
	// Unspent skill points
	SkillPoints int          `json:"skill_points"`
	SkillGroups []SkillGroup `json:"skill_groups"`
	// The period the roster was read in
	PeriodID int `json:"period_id"`
}

