// SkillGroup: One of a player's skill groups. Tiers 1..`level` are filled, the next `buyable` can be bought with skill points, and the last `locked` are above the player's potential `cap`. A level above the cap came from the player's ratings; nothing can be bought then.
type SkillGroup struct {
	Name  string `json:"name"`
	Level int    `json:"level"`
	// Potential: the highest tier that can be bought
	Cap int `json:"cap"`
	// Tier count (20)
	Max int `json:"max"`
	// The group's rating
	Overall int `json:"overall"`
	// Tiers still buyable: `cap - level`, at least 0
	Buyable int `json:"buyable"`
	// Tiers above the cap: `max - max(cap, level)`
	Locked int `json:"locked"`
}

// SkillSnapshot is a Dynasty API schema.
type SkillSnapshot struct {
	PeriodID   int    `json:"period_id"`
	SeasonText string `json:"season_text"`
	Overall    int    `json:"overall"`
	// Unspent skill points
	SkillPoints int          `json:"skill_points"`
	SkillGroups []SkillGroup `json:"skill_groups"`
	// Level change by group since the previous snapshot, where it changed. Levels bought with skill points (the game also auto-progresses players)
	LevelsGained map[string]int `json:"levels_gained,omitempty"`
	// Skill points since the previous snapshot: down when spent, up when earned
	PointsChange int `json:"points_change"`
}

