// GetLeague: League summary, sync status, current period and cached seasons
//
// GET /v1/league
func (c *Client) GetLeague(ctx context.Context) (*LeagueResponse, error) {
	out := new(LeagueResponse)
	if err := c.t.do(ctx, c.dynastyID, "GET", "/league", nil, nil, out); err != nil {
		return nil, err
	}
	return out, nil
}

