// ListSchedule: A season's games
//
// GET /v1/schedule
func (c *Client) ListSchedule(ctx context.Context, params *ListScheduleParams) (*ScheduleResponse, error) {
	q := url.Values{}
	if params != nil {
		if params.Season != nil {
			q.Set("season", strconv.Itoa(*params.Season))
		}
		if params.Week != nil {
			q.Set("week", strconv.Itoa(*params.Week))
		}
		if params.Team != nil {
			q.Set("team", strconv.Itoa(*params.Team))
		}
		if params.Played != nil {
			q.Set("played", strconv.FormatBool(*params.Played))
		}
		if params.UserGames != nil {
			q.Set("user_games", strconv.FormatBool(*params.UserGames))
		}
	}
	out := new(ScheduleResponse)
	if err := c.t.do(ctx, c.dynastyID, "GET", "/schedule", q, nil, out); err != nil {
		return nil, err
	}
	return out, nil
}

